// ENG-1884 proof: which canvas shapes offer "Convert To", and where the node lands.
const PAGE_TITLE = `Canvas/ENG-1884 verify ${Date.now()}`;

const FIXTURES = [
  { key: "text-with-text", type: "text", text: "text shape", expect: true },
  { key: "text-empty", type: "text", text: "", expect: true },
  { key: "geo-with-text", type: "geo", text: "geo with text", expect: true },
  { key: "geo-empty", type: "geo", text: "", expect: false },
  { key: "geo-whitespace", type: "geo", text: "   ", expect: false },
  { key: "note-with-text", type: "note", text: "note with text", expect: true },
  { key: "note-empty", type: "note", text: "", expect: false },
  { key: "arrow-with-text", type: "arrow", text: "arrow label", expect: false },
  { key: "geo-locked", type: "geo", text: "locked", expect: false, locked: true },
];

const waitFor = async (page, fn, timeout = 60000, label = "condition") => {
  const start = Date.now();
  for (;;) {
    if (await page.evaluate(fn)) return;
    if (Date.now() - start > timeout) throw new Error(`timeout waiting for ${label}`);
    await page.waitForTimeout(250);
  }
};

const closeRoamDialogs = async (page) => {
  for (let i = 0; i < 4; i += 1) {
    const open = await page.evaluate(() =>
      Boolean(document.querySelector(".bp3-dialog, .bp3-overlay-open, .rm-settings")),
    );
    if (!open) return;
    await page.keyboard.press("Escape");
    await page.waitForTimeout(400);
  }
};

export default {
  async ready({ page }) {
    await closeRoamDialogs(page);
    await page.evaluate(async (title) => {
      await window.roamAlphaAPI.data.page.create({ page: { title } });
      const uid = window.roamAlphaAPI.q(
        `[:find ?u . :where [?p :node/title "${title}"] [?p :block/uid ?u]]`,
      );
      await window.roamAlphaAPI.ui.mainWindow.openPage({ page: { uid } });
    }, PAGE_TITLE);
    await page.waitForSelector(".tl-canvas", { timeout: 60000 });
    await waitFor(page, `Boolean(window.tldrawApps && window.tldrawApps[${JSON.stringify(PAGE_TITLE)}])`,
      60000, "tldraw editor");
    await closeRoamDialogs(page);
    return true;
  },

  async run({ page }) {
    const ids = await page.evaluate(
      ({ title, fixtures }) => {
        const editor = window.tldrawApps[title];
        editor.selectAll().deleteShapes(editor.getSelectedShapeIds());
        const made = {};
        fixtures.forEach((f, i) => {
          const id = `shape:eng1884_${f.key.replace(/-/g, "_")}`;
          const base = { id, type: f.type, x: 100 + i * 300, y: 200 };
          if (f.type === "arrow") {
            editor.createShapes([{ ...base, props: { text: f.text, start: { x: 0, y: 0 }, end: { x: 180, y: 0 } } }]);
          } else if (f.type === "geo") {
            editor.createShapes([{ ...base, props: { geo: "rectangle", w: 220, h: 140, text: f.text } }]);
          } else {
            editor.createShapes([{ ...base, props: { text: f.text } }]);
          }
          if (f.locked) editor.updateShapes([{ id, type: f.type, isLocked: true }]);
          made[f.key] = id;
        });
          return made;
      },
      { title: PAGE_TITLE, fixtures: FIXTURES },
    );

    const gate = [];
    for (const f of FIXTURES) {
      const pt = await page.evaluate(
        ({ title, id }) => {
          const editor = window.tldrawApps[title];
          editor.selectNone();
          editor.select(id);
          const b = editor.getShapePageBounds(id);
          // Centre the camera so the click never lands off-canvas or under a panel.
          editor.setCamera({ x: -b.midX + 400, y: -b.midY + 300, z: 1 });
          const v = editor.pageToViewport({ x: b.midX, y: b.midY });
          const rect = document.querySelector(".tl-container").getBoundingClientRect();
          return { x: rect.left + v.x, y: rect.top + v.y, w: rect.width, h: rect.height };
        },
        { title: PAGE_TITLE, id: ids[f.key] },
      );

      await page.mouse.click(pt.x, pt.y, { button: "right" });
      await page.waitForTimeout(600);

      const probe = await page.evaluate(() => {
        const els = Array.from(
          document.querySelectorAll("[class*='contextmenu'],[role='menu'],[class*='tlui-menu']"),
        );
        const text = els.map((e) => e.innerText || "").join(" | ");
        return {
          // tldraw's own entries prove the menu opened, so "no menu" never reads
          // as "menu without Convert To". A locked shape gets a reduced menu.
          menuOpened: /Duplicate|Delete|Copy as|Export as|Select all/i.test(text),
          hasConvertTo: /Convert To/.test(text),
        };
      });
      await page.keyboard.press("Escape");
      await page.waitForTimeout(250);

      gate.push({
        fixture: f.key,
        expected: f.expect,
        menuOpened: probe.menuOpened,
        actual: probe.hasConvertTo,
        pass: probe.menuOpened && f.expect === probe.hasConvertTo,
      });
    }

    const harnessBroken = gate.some((g) => !g.menuOpened);
    const failures = gate.filter((g) => !g.pass);
    return {
      page: PAGE_TITLE,
      harnessBroken,
      gate,
      gateFailures: failures,
      gatePassed: !harnessBroken && failures.length === 0,
    };
  },

  async cleanup({ page }) {
    await page.evaluate(async (title) => {
      const uid = window.roamAlphaAPI.q(
        `[:find ?u . :where [?p :node/title "${title}"] [?p :block/uid ?u]]`,
      );
      if (uid) await window.roamAlphaAPI.data.page.delete({ page: { uid } });
    }, PAGE_TITLE);
  },
};

