// Run 2 (dist-nofix, 7fd5a170): open the pre-PR cloud room. Read-only.
import { installEditorFinder, readState, closeRoamDialogs, openPage, snapshotEditor, attachLogs, canvasState, tryWait } from "./common.mjs";

export default {
  async ready({ page }) {
    await closeRoamDialogs(page);
    return page.evaluate(() => Boolean(window.roamAlphaAPI && window.roamjs?.extension?.queryBuilder));
  },
  async run({ page, outDir }) {
    const logs = attachLogs(page);
    await installEditorFinder(page);
    const { T, U } = readState();
    const out = { page: T.cloud };
    await openPage(page, U.cloud);
    await page.waitForTimeout(10000);
    out.at10s = await canvasState(page);
    await page.screenshot({ path: `${outDir}/s2-nofix-10s.png` });
    out.loadedWithin60s = await tryWait(page, () => (window.__eng1955Ed?.()?.getCurrentPageShapes().length ?? 0) >= 6, null, 50000, "shapes");
    out.at60s = await canvasState(page);
    out.snapshot = await snapshotEditor(page, T.cloud);
    await page.screenshot({ path: `${outDir}/s2-nofix-60s.png` });
    out.logs = logs.slice(0, 40);
    return out;
  },
};
EOF
