D=/Users/trang.doan/Desktop/code/discourse-graph/.claude/worktrees/eng-1955-full-migration-to-discourse-relation-only/local/roam-playwright/eng1955; cat > $D/run3-head.mjs <<'EOF'
// Run 3 (HEAD dist): S3 a-c on the pre-PR cloud room, then S4b local migration check.
import { installEditorFinder, readState, closeRoamDialogs, openPage, snapshotEditor, rawPageStore, attachLogs, canvasState, tryWait, REL } from "./common.mjs";

const titleIs = (t) => document.querySelector(".rm-title-display")?.innerText.trim() === t;

export default {
  async ready({ page }) {
    await closeRoamDialogs(page);
    return page.evaluate(() => Boolean(window.roamAlphaAPI && window.roamjs?.extension?.queryBuilder));
  },
  async run({ page, outDir }) {
    const logs = attachLogs(page);
    await installEditorFinder(page);
    const { T, U } = readState();
    const out = { page: T.cloud };
    await openPage(page, U.cloud);
    out.loaded = await tryWait(page, (t) => document.querySelector(".rm-title-display")?.innerText.trim() === t && (window.__eng1955Ed?.()?.getCurrentPageShapes().length ?? 0) >= 6, T.cloud, 60000, "shapes");
    out.state = await canvasState(page);
    await page.waitForTimeout(2000);
    out.before = await snapshotEditor(page, T.cloud);
    out.labelsVisible = await page.evaluate(() => {
      const txt = document.querySelector(".roamjs-tldraw-canvas-container")?.innerText || "";
      return { Supports: txt.includes("Supports"), Informs: txt.includes("Informs") };
    });
    await page.screenshot({ path: `${outDir}/s3-head-loaded.png` });
    const errsBefore = logs.length;

    // (a) new relation arrow the way relationCreation.ts does it.
    out.a = await page.evaluate((rel) => {
      const ed = window.__eng1955Ed();
      const id = "shape:eng1955NewBQ";
      const b = ed.getShapePageBounds("shape:eng1955B");
      ed.createShape({ id, type: "discourse-relation", x: b.midX, y: b.midY, props: { text: "Informs", relationTypeId: rel, start: { x: 0, y: 0 }, end: { x: 0, y: 0 }, arrowheadEnd: "arrow", arrowheadStart: "none" } });
      const bp = { normalizedAnchor: { x: 0.5, y: 0.5 }, isPrecise: false, isExact: false };
      ed.createBinding({ type: "discourse-relation", fromId: id, toId: "shape:eng1955B", props: { terminal: "start", ...bp } });
      ed.createBinding({ type: "discourse-relation", fromId: id, toId: "shape:eng1955Q", props: { terminal: "end", ...bp } });
      const s = ed.getShape(id);
      return { type: s?.type, relationTypeId: s?.props.relationTypeId, bindingTypes: ed.getBindingsFromShape(id, "discourse-relation").map((x) => x.type) };
    }, REL.informs);
    await page.waitForTimeout(1500);

    // (b) edit legacy arrows: move a connected node and bend a legacy arrow.
    out.b = await page.evaluate(() => {
      const ed = window.__eng1955Ed();
      const a = ed.getShape("shape:eng1955A");
      ed.updateShapes([{ id: a.id, type: a.type, x: a.x + 150, y: a.y + 40 }]);
      const arr = ed.getShape("shape:eng1955ArrAQ");
      ed.updateShapes([{ id: arr.id, type: arr.type, props: { bend: 60 } }]);
      const after = ed.getShape("shape:eng1955ArrAQ");
      const bindings = ed.getBindingsFromShape(arr.id, arr.type).map((x) => `${x.props.terminal}->${x.toId}`);
      return { arrType: after.type, bend: after.props.bend, nodeX: ed.getShape(a.id).x, bindings };
    });
    await page.waitForTimeout(1500);

    // (c) delete a legacy arrow.
    out.c = await page.evaluate(() => {
      const ed = window.__eng1955Ed();
      ed.deleteShapes(["shape:eng1955ArrEA"]);
      return { stillThere: Boolean(ed.getShape("shape:eng1955ArrEA")), orphanBindings: ed.store.allRecords().filter((r) => r.typeName === "binding" && r.fromId === "shape:eng1955ArrEA").length };
    });
    await page.waitForTimeout(15000); // let the room persist
    out.editErrors = logs.slice(errsBefore);
    out.afterEdits = await snapshotEditor(page, T.cloud);
    await page.evaluate(() => { window.__eng1955Ed().zoomToFit(); return true; });
    await page.waitForTimeout(800);
    await page.screenshot({ path: `${outDir}/s3-head-after-edits.png` });

    // --- S4b: local canvas created by main ---
    out.s4bRawBefore = await rawPageStore(page, U.local);
    await openPage(page, U.local);
    out.s4bLoaded = await tryWait(page, (t) => document.querySelector(".rm-title-display")?.innerText.trim() === t && (window.__eng1955Ed?.()?.getCurrentPageShapes().length ?? 0) >= 5, T.local, 60000, "local shapes");
    await page.waitForTimeout(2000);
    out.s4b = await snapshotEditor(page, T.local);
    out.s4bRawAfterOpen = await rawPageStore(page, U.local);
    await page.screenshot({ path: `${outDir}/s4b-head-local.png` });

    // Remount the cloud canvas in-session (new sync connection).
    await openPage(page, U.cloud);
    out.remountLoaded = await tryWait(page, (t) => document.querySelector(".rm-title-display")?.innerText.trim() === t && (window.__eng1955Ed?.()?.getCurrentPageShapes().length ?? 0) >= 6, T.cloud, 60000, "shapes after remount");
    await page.waitForTimeout(2000);
    out.remount = await snapshotEditor(page, T.cloud);
    out.logs = logs.slice(0, 30);
    return out;
  },
};
EOF
